using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using TasiaCraft;
public static partial class MediaBinTest {
 static DataObject DragData(Project p,params TasiaCraft.Media[] media){return new DataObject(MediaBinDragPayload.Format,new MediaBinDragPayload(p,media));}
 static DragDropEffects Drop(Editor e,IDataObject data,Point point){return (DragDropEffects)Call(e,"DropMediaSelection",data,point);}
 static bool Press(ListBox bin,ListBoxItem item,bool up){var args=new MouseButtonEventArgs(Mouse.PrimaryDevice,0,MouseButton.Left){RoutedEvent=up?UIElement.PreviewMouseLeftButtonUpEvent:UIElement.PreviewMouseLeftButtonDownEvent,Source=item};bin.RaiseEvent(args);return args.Handled;}
 static void DragTests(Editor editor,Project original,LivePreview preview){
  Check(!MediaBinDragPayload.BeyondThreshold(new Point(4,5),new Point(7,8),4,4),"sub-threshold pointer movement does not drag");Check(MediaBinDragPayload.BeyondThreshold(new Point(4,5),new Point(8,5),4,4),"horizontal threshold starts drag");Check(MediaBinDragPayload.BeyondThreshold(new Point(4,5),new Point(4,1),4,4),"negative vertical threshold starts drag");
  Reset(editor,original);Set(editor,"mediaSort","Name");Set(editor,"mediaDescending",false);Call(editor,"Panel","Media");ChooseBin(editor,original.Media[0].Id,original.Media[2].Id);var bin=(ListBox)Field(editor,"bin");var item=bin.Items.OfType<ListBoxItem>().First(i=>i.IsSelected);int executions=0;IDataObject captured=null;Set(editor,"mediaDragExecutor",new Func<DependencyObject,IDataObject,DragDropEffects,DragDropEffects>((target,dragData,effect)=>{executions++;captured=dragData;return DragDropEffects.None;}));
  bool downHandled=Press(bin,item,false);Check(bin.SelectedItems.Count==2,"press on selected bin item preserves multiple selection for drag");var move=(Action<Point,bool>)Field(editor,"mediaDragMove");var origin=Mouse.GetPosition(bin);move(origin,true);Check(executions==0,"wired drag state ignores movement below threshold");move(new Point(origin.X+100,origin.Y),true);Check(executions==1&&captured!=null,"wired drag invokes executor after threshold (down handled="+downHandled+", selected="+item.IsSelected+")");var payload=(MediaBinDragPayload)captured.GetData(MediaBinDragPayload.Format);Check(object.ReferenceEquals(payload.Source,P(editor))&&payload.Media.Length==2,"actual DataObject retains project and every selected source");Check(payload.Media.Select(m=>m.Id).SequenceEqual(bin.Items.OfType<ListBoxItem>().Where(i=>i.IsSelected).Select(i=>((TasiaCraft.Media)i.Tag).Id)),"drag payload follows visible sorted bin order");var copy=payload.Media;copy[0]=null;Check(payload.Media.All(m=>m!=null),"payload protects its source array from caller mutation");move(new Point(origin.X+200,origin.Y),true);Check(executions==1,"one press starts at most one drag even after cancellation");Check(Undos(editor)==0&&!((bool)Field(editor,"dirty")),"cancelled drag leaves project and history unchanged");
  Press(bin,item,false);Press(bin,item,true);Check(bin.SelectedItems.Count==1&&bin.SelectedItem==item,"release without drag selects the clicked item");ChooseBin(editor,original.Media[0].Id,original.Media[2].Id);Press(bin,item,false);move(origin,false);move(new Point(origin.X+100,origin.Y),true);Check(executions==1,"released pointer cancels pending drag");Press(bin,item,false);Set(editor,"busy",true);move(new Point(origin.X+100,origin.Y),true);Check(executions==1,"busy state blocks pending drag execution");Set(editor,"busy",false);Press(bin,item,true);Press(bin,item,false);Call(editor,"Refresh");move(new Point(origin.X+100,origin.Y),true);Check(executions==1,"rebuilt stale bin cannot initiate a drag");Set(editor,"mediaDragExecutor",null);
  Reset(editor,original);Set(editor,"zoom",40.0);Set(editor,"projectConfigured",true);var p=P(editor);string baseline=json.Serialize(p);var media=new[]{p.Media[2],p.Media[0]};var data=DragData(p,media);double top=(double)typeof(Editor).GetProperty("TracksTop",flags).GetValue(editor,null);var point=new Point(110+2*40,top+64+10);Check((DragDropEffects)Call(editor,"MediaDragOverEffects",data,point)==DragDropEffects.None,"drag-over cursor rejects locked target");Check(Drop(editor,data,point)==DragDropEffects.None,"locked target track rejects batch drop");Check(json.Serialize(p)==baseline&&Undos(editor)==0,"locked drop is atomic");point.Y=top+128+10;Check((DragDropEffects)Call(editor,"MediaDragOverEffects",data,point)==DragDropEffects.Copy,"drag-over cursor accepts valid unlocked target");Check(Drop(editor,data,point)==DragDropEffects.Copy,"batch drop inserts at unlocked target track");var inserted=P(editor).Clips.Skip(original.Clips.Count).ToArray();Check(inserted.Length==2&&inserted[0].Start==2&&inserted[1].Start==7&&inserted.All(c=>c.Track==0),"drop coordinates map through zoom and track lanes");Check(inserted.Select(c=>c.MediaId).SequenceEqual(media.Select(m=>m.Id))&&Selected(editor).Count==2,"drop preserves payload order and selects batch");Check(Undos(editor)==1,"drop creates one undo checkpoint");string after=json.Serialize(P(editor));var pixels=BatchPixels(preview,P(editor),8);int center=(90*320+160)*4;Check(pixels[center+2]>200&&pixels[center]<30,"dropped second source renders red in preview");string export=Path.Combine(root,"drag.mp4"),rgb=Path.Combine(root,"drag.rgb");Engine.Render(P(editor),export,null);Engine.Run("ffmpeg","-y -v error -ss 8 -i "+Engine.Quote(export)+" -frames:v 1 -pix_fmt rgb24 -f rawvideo "+Engine.Quote(rgb));var decoded=File.ReadAllBytes(rgb);Check(decoded[(90*320+160)*3]>200&&decoded[(90*320+160)*3+2]<30,"decoded drop export matches preview");string save=Path.Combine(root,"drag.tasiaproj");Engine.Save(P(editor),save);Check(json.Serialize(Engine.Load(save))==after,"dragged sequence saves and reopens exactly");Call(editor,"Undo");Check(json.Serialize(P(editor))==baseline,"one undo removes entire dragged batch");Call(editor,"Redo");Check(json.Serialize(P(editor))==after,"redo restores dragged batch exactly");Call(editor,"Undo");p=P(editor);baseline=json.Serialize(p);
  Check(Drop(editor,data,point)==DragDropEffects.None&&Undos(editor)==0,"payload from project replaced by undo is rejected");Check(Drop(editor,DragData(Clone(p),p.Media[0]),point)==DragDropEffects.None,"foreign project payload rejected");Check(Drop(editor,new DataObject(MediaBinDragPayload.Format,"malformed"),point)==DragDropEffects.None,"malformed payload rejected");Check(Drop(editor,new DataObject("Unrelated","data"),point)==DragDropEffects.None,"unrelated data ignored");Check(Drop(editor,DragData(p,new TasiaCraft.Media{Id=p.Media[0].Id,Path=p.Media[0].Path}),point)==DragDropEffects.None,"stale source reference rejected");Check(Drop(editor,DragData(p,p.Media[0]),new Point(double.NaN,0))==DragDropEffects.None,"nonfinite drop coordinates rejected");Set(editor,"busy",true);Check(Drop(editor,DragData(p,p.Media[0]),point)==DragDropEffects.None,"busy drop rejected");Set(editor,"busy",false);string path=p.Media[2].Path;p.Media[2].Path=Path.Combine(root,"absent-drag.png");Check(Drop(editor,DragData(p,p.Media[0],p.Media[2]),point)==DragDropEffects.None&&p.Clips.Count==original.Clips.Count&&Undos(editor)==0,"missing later source rejects drop without partial clips");p.Media[2].Path=path;Check(json.Serialize(p)==baseline,"all failed drops preserve original model");
  var timeline=(Canvas)Field(editor,"timeline");var ctor=typeof(DragEventArgs).GetConstructors(BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Single();var routed=(DragEventArgs)ctor.Invoke(new object[]{DragData(p,p.Media[0]),DragDropKeyStates.LeftMouseButton,DragDropEffects.Copy,timeline,new Point(110,top+128+10)});routed.RoutedEvent=UIElement.DropEvent;timeline.RaiseEvent(routed);Check(routed.Handled&&routed.Effects==DragDropEffects.Copy&&P(editor).Clips.Count==original.Clips.Count+1,"actual routed WPF Drop handler inserts a single-source payload");Call(editor,"Undo");p=P(editor);Check(Drop(editor,DragData(p,p.Media[0]),new Point(-10,-10))==DragDropEffects.Copy&&P(editor).Clips.Last().Start==0&&P(editor).Clips.Last().Track==p.TrackCount-1,"outer top-left drop clamps time and track");Call(editor,"Undo");p=P(editor);Check(Drop(editor,DragData(p,p.Media[0]),new Point(110,1e10))==DragDropEffects.Copy&&P(editor).Clips.Last().Track==0,"drop below timeline clamps to bottom track");Call(editor,"Undo");Set(editor,"mediaSort","Type");Set(editor,"mediaDescending",false);Set(editor,"projectConfigured",false);Reset(editor,original);
 }
}
